window.ScripturaLexicons.BDAG_PART_0246 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-01\" data-source=\"BDAG\" data-search=\"Νινευής nome próprio masculino; variante textual Ninévés; suposto nome do rico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νινευής</td><td>nome próprio masculino; variante textual</td><td>Ninévés; suposto nome do rico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-02\" data-source=\"BDAG\" data-search=\"Νινευίτης, ου, ὁ substantivo masculino étnico ninivita BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νινευίτης, ου, ὁ</td><td>substantivo masculino étnico</td><td>ninivita</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-03\" data-source=\"BDAG\" data-search=\"νιπτήρ, ῆρος, ὁ substantivo masculino bacia; recipiente de lavar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νιπτήρ, ῆρος, ὁ</td><td>substantivo masculino</td><td>bacia; recipiente de lavar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-04\" data-source=\"BDAG\" data-search=\"νίπτω verbo lavar; lavar-se; prestar serviço lavando os pés BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νίπτω</td><td>verbo</td><td>lavar; lavar-se; prestar serviço lavando os pés</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-05\" data-source=\"BDAG\" data-search=\"νοέω verbo compreender; considerar; imaginar; ter em mente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νοέω</td><td>verbo</td><td>compreender; considerar; imaginar; ter em mente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-06\" data-source=\"BDAG\" data-search=\"νόημα, ατος, τό substantivo neutro pensamento; desígnio; mente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νόημα, ατος, τό</td><td>substantivo neutro</td><td>pensamento; desígnio; mente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-07\" data-source=\"BDAG\" data-search=\"νόθος, η, ον adjetivo ilegítimo; nascido fora do matrimônio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νόθος, η, ον</td><td>adjetivo</td><td>ilegítimo; nascido fora do matrimônio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-08\" data-source=\"BDAG\" data-search=\"νομή, ῆς, ἡ substantivo feminino pastagem; propagação destrutiva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομή, ῆς, ἡ</td><td>substantivo feminino</td><td>pastagem; propagação destrutiva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-09\" data-source=\"BDAG\" data-search=\"νομίζω verbo observar costume; supor; considerar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομίζω</td><td>verbo</td><td>observar costume; supor; considerar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-10\" data-source=\"BDAG\" data-search=\"νομικός, ή, όν adjetivo e substantivo masculino jurídico; versado na lei; jurista BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομικός, ή, όν</td><td>adjetivo e substantivo masculino</td><td>jurídico; versado na lei; jurista</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-11\" data-source=\"BDAG\" data-search=\"νόμιμος, η, ον adjetivo e substantivo neutro legal; conforme a norma; prescrições BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νόμιμος, η, ον</td><td>adjetivo e substantivo neutro</td><td>legal; conforme a norma; prescrições</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-12\" data-source=\"BDAG\" data-search=\"νομίμως advérbio legalmente; de acordo com as regras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομίμως</td><td>advérbio</td><td>legalmente; de acordo com as regras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-13\" data-source=\"BDAG\" data-search=\"νόμισμα, ατος, τό substantivo neutro moeda; dinheiro cunhado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νόμισμα, ατος, τό</td><td>substantivo neutro</td><td>moeda; dinheiro cunhado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-14\" data-source=\"BDAG\" data-search=\"νομοδιδάσκαλος, ου, ὁ substantivo masculino mestre da lei BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομοδιδάσκαλος, ου, ὁ</td><td>substantivo masculino</td><td>mestre da lei</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-15\" data-source=\"BDAG\" data-search=\"νομοθεσία, ας, ἡ substantivo feminino promulgação de leis; legislação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομοθεσία, ας, ἡ</td><td>substantivo feminino</td><td>promulgação de leis; legislação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-16\" data-source=\"BDAG\" data-search=\"νομοθετέω verbo legislar; ordenar legalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομοθετέω</td><td>verbo</td><td>legislar; ordenar legalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-17\" data-source=\"BDAG\" data-search=\"νομοθέτης, ου, ὁ substantivo masculino legislador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νομοθέτης, ου, ὁ</td><td>substantivo masculino</td><td>legislador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-18\" data-source=\"BDAG\" data-search=\"νόμος, ου, ὁ substantivo masculino costume; norma; lei; lei mosaica; Escrituras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νόμος, ου, ὁ</td><td>substantivo masculino</td><td>costume; norma; lei; lei mosaica; Escrituras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-19\" data-source=\"BDAG\" data-search=\"νοσέω verbo estar enfermo; desejar algo de modo mórbido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νοσέω</td><td>verbo</td><td>estar enfermo; desejar algo de modo mórbido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0246-20\" data-source=\"BDAG\" data-search=\"νόσημα, ατος, τό substantivo neutro doença; enfermidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νόσημα, ατος, τό</td><td>substantivo neutro</td><td>doença; enfermidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0246-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νινευής</h1><div class=\"entry-meta\"><span>nome próprio masculino; variante textual</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νινευής</span> (<span class=\"greek\">Νινευε</span> copta; talvez «ninguém»), Ninévés, suposto nome do homem rico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:19</a> (ver Tdf. ad loc.; <span class=\"greek\">Νευης</span> P75, ver <span class=\"greek\">Νευης</span>). HCadbury, JBL 81, ’62, 399–402; KGrobel, NTS 10, ’63/64, 373–82; GKilpatrick, The Bodmer and Mississippi Collection: Greek Roman Byzantine Studies 4, ’63, 39f; PWeigandt, Zum Text v. Joh. 10, 7: NovT 9, ’67, 47f. Ver também LLefort, Le nom du mauvais riche et la trad. copte, ZNW 37, ’38, 65–72. Cf. o destino de certo Ninos: Phoenix 1 (Coll. Alex. p 231f).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νινευίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino étnico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νινευίτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (também -<span class=\"greek\">είτης</span>), ninivita; no plural, habitantes de Nínive, exemplos de arrependimento contrapostos aos contemporâneos de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:32</a>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">Νινευίταις</span>, aos ninivitas, versículo 30. A pregação de arrependimento de Jonas entre eles 1 Cl 7:7.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νιπτήρ, ῆρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νιπτήρ</span>, <span class=\"greek\">ῆρος</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">νίπτω</span>; cf. Hdt. 2, 172 <span class=\"greek\">ποδανιπτήρ</span>; uma inscrição cipriota da época romana apresenta o acusativo <span class=\"greek\">νιπτῆρα</span>: ASakellarios, <span class=\"greek\">Τα</span> <span class=\"greek\">Κυπριακα</span> I 1890, p. 191 nº 2=GDI 123, 8; Lex. Vindob. p. 128, 16; TestAbr A 3 p. 80, 11 [Stone p. 8; ver NTS 1, ’54, 220]; TestJob 25:6), bacia (para lavar) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:5</a> (<span class=\"greek\">ποδονιπτήρ</span> P66).—DELG s.v. <span class=\"greek\">νίζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νίπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νίπτω</span>, 1º aoristo <span class=\"greek\">ἔνιψα</span>, médio <span class=\"greek\">ἐνιψάμην</span>, imperativo <span class=\"greek\">νίψαι</span> (B-D-F §73; W-S. §15; Mlt-H. 250). Passivo: futuro, 3ª pessoa do singular <span class=\"greek\">νιφήσεται</span> Lev 15:11f; perfeito, 3ª pessoa do singular <span class=\"greek\">νένιπται</span> (Hippocr.; Epict. [ver 1a abaixo]; LXX; Jos., Ant. 8, 87).</p><p class=\"entry-text\">① Limpar com o uso de água, lavar.</p><p class=\"entry-text\">ⓐ Ativo: lavar, com acusativo <span class=\"greek\">τὶ</span> de alguma coisa: <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span>, os pés (Epict. 1, 19, 5 <span class=\"greek\">νίπτω</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόδας</span>; Vi. Aesopi G 61 P.; Gen 43:24; 1 Km 25:41; TestAbr A 6 p. 83, 19 [Stone p. 14]; JosAs 7:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:5</a>f, 8a, 12, 14a (sobre «lavar os pés», ver <span class=\"greek\">λούω</span> 2a; para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:14</a>b ver 2 abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:10</a> (como ato de hospitalidade, cf. 2 abaixo). <span class=\"greek\">τινά</span>, alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:8</a>b.</p><p class=\"entry-text\">ⓑ Médio: lavar-se ou lavar para si (TestLevi 9:11 <span class=\"greek\">λούου</span> … <span class=\"greek\">νίπτου</span>).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Eu me lavo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:7</a>b, 11ab, 15; 13:10 v.l. (caso <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόδας</span> seja omitido); Ox 840, 34f. <span class=\"greek\">νίπτεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κολυμβήθραν</span>, lavar-se, banhar-se na piscina (cf. Epict. 3, 22, 71 <span class=\"greek\">ἵν</span>’ <span class=\"greek\">αὐτὸ</span> [sc. <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span>] <span class=\"greek\">λούσῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σκάφην</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:7</a>a.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Eu lavo (para mim), com acusativo: <span class=\"greek\">ν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span>, lavar o próprio rosto (Artem. 4, 41; Achmes 143, 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:17</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span>, lavar as próprias mãos (Diod S 23, 2, 1; Ex 30:19; Lev 15:11) 15:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:3</a> (ver FSchulthess, ZNW 21, 1922, 233); GPt 1:1. <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> (Hes., Fgm. 122 Rz.; Artem. 5, 55; Gen 19:2; Judg 19:21; JosAs 20:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:10</a>. JHorst, D. Worte Jesu über d. kult. Reinheit: StKr 87, 1914, 429–54. Branscomb (ver <span class=\"greek\">νόμος</span>, final) 156–60. WGrossouw, NovT 8, ’66, 124–31.</p><p class=\"entry-text\">② Prestar serviço generoso, lavar os pés, como sentido da expressão unitária <span class=\"greek\">νίπτειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:14</a>b (ver 1a acima). JATRobinson, The Significance of Footwashing, OCullmann Festschr., ’62, 144–47.—B. 578f. DELG s.v. <span class=\"greek\">νίζω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νοέω</span>, futuro <span class=\"greek\">νοήσω</span> LXX; 1º aoristo <span class=\"greek\">ἐνόησα</span>; perfeito <span class=\"greek\">νενόηκα</span>; mais-que-perfeito <span class=\"greek\">ἐνενοήκειν</span> (Just.). Passivo: futuro, 3ª pessoa do singular <span class=\"greek\">νοηθήσεται</span> Sir 14:21; infinitivo aoristo <span class=\"greek\">νοηθῆναι</span> (Just.) (Hom. e posteriores; papiros, LXX, En, TestSol 11:1 P.; TestAbr B 6 p. 110, 22 [Stone p. 68]; Test12Patr; ApcMos 18; EpArist, Philo, Joseph., apologistas exceto Ar.).</p><p class=\"entry-text\">① Apreender ou compreender algo com base na reflexão cuidadosa, perceber, apreender, entender, alcançar uma compreensão.</p><p class=\"entry-text\">ⓐ Com objeto no acusativo (X., An. 3, 4, 44; Jos., Vi. 298; SibOr 5, 65): <span class=\"greek\">τὴν</span> <span class=\"greek\">σύνεσίν</span> <span class=\"greek\">μου</span>, meu discernimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:4</a>. <span class=\"greek\">δικαίως</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span>, compreender corretamente os mandamentos 10:12b. <span class=\"greek\">τὰς</span> <span class=\"greek\">παραβολάς</span>, compreender as parábolas Hm 10, 1, 4; <span class=\"greek\">οὐ</span> <span class=\"greek\">δύναμαι</span> <span class=\"greek\">νοῆσαι</span>, não posso compreendê-las Hs 5, 3, 1 (cf. Pr 1:6); (com <span class=\"greek\">συνιέναι</span>, como em 10:12a) <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λεγόμενα</span>, tudo o que é dito Hm 10, 1, 6a (Just., D. 73, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">λεγόμενον</span>); cf. 6b; <span class=\"greek\">τῆς</span> <span class=\"greek\">βασάνου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δύναμιν</span>, o poder do tormento Hs 6, 4, 3a. <span class=\"greek\">τὴν</span> <span class=\"greek\">πρᾶξιν</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">ποιεῖ</span>, aquilo que ele está fazendo 6, 5, 3. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπουράνια</span>, compreender as coisas celestiais ITr 5:2; <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Hm 12, 4, 2; Hs 5, 3, 1 (com <span class=\"greek\">γινώσκειν</span> [como em Plato, Rep. 6, 508d e e]); <span class=\"greek\">τοὺς</span> <span class=\"greek\">χρόνους</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀπάτης</span> 6, 5, 1. Oração relativa como objeto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:7</a>; Dg 8:11; IRo 6:3. <span class=\"greek\">ταῦτα</span> 10:12a; Hs 5, 5, 4. <span class=\"greek\">αὐτά</span> 6, 5, 2; 9, 2, 6b; <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ν</span>., nada compreender Hv 3, 6, 5; Hs 9, 14, 4. <span class=\"greek\">ὅλως</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ν</span>., absolutamente nada compreender Hm 4, 2, 1. Também <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὅλως</span> <span class=\"greek\">ν</span>. 10, 1, 5 (<span class=\"greek\">μηδὲν</span> <span class=\"greek\">τούτων</span> Just., D. 125, 5). <span class=\"greek\">ὅσα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνασαι</span> <span class=\"greek\">νοῆσαι</span>, tudo o que não consegues compreender Hs 9, 2, 6a. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">δύναμαι</span> <span class=\"greek\">νοῆσαι</span>, tampouco consigo compreender coisa alguma (a esse respeito) 9, 9, 2.—Com acusativo de pessoa (Mel., P. 82, 605 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐνόησας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>): acerca do anjo da maldade, <span class=\"greek\">πῶς</span> <span class=\"greek\">νοήσω</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπίσταμαι</span>, não sei como reconhecê-lo Hm 6, 2, 5.—Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> em lugar de objeto: <span class=\"greek\">ἔτι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">νενόηκα</span> <span class=\"greek\">ὅλως</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χρόνου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπάτης</span>, ainda não compreendi inteiramente a respeito do tempo do prazer enganoso Hs 6, 5, 1 v.l.—Passivo: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀόρατα</span> … <span class=\"greek\">νοούμενα</span> <span class=\"greek\">καθορᾶται</span>, as coisas invisíveis … são claramente percebidas (pelo olho do entendimento) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:20</a> (<span class=\"greek\">νοῆσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>: Herm. Wr. 11, 20b; 12, 20b e PGM 3, 597; Orphica Fgm. 6 Abel [Eus., PE 13, 12, 5; cf. Denis 165, linha 5f; Holladay p. 128 linha 16, ver aparato] <span class=\"greek\">οὐδέ</span> <span class=\"greek\">τις</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰσοράᾳ</span> <span class=\"greek\">ψυχῶν</span> <span class=\"greek\">θνητῶν</span>, <span class=\"greek\">νῷ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">εἰσοράαται</span> (diferente em Theosophien §56, verso 10 [p. 180]. Ver <span class=\"greek\">γνωστός</span> 2). Sobre o <span class=\"greek\">λόγος</span>: <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἀπίστων</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">νοούμενος</span> Dg 11:2 (cf. Ath. 18, 2 <span class=\"greek\">λόγῳ</span> <span class=\"greek\">υἱῷ</span> <span class=\"greek\">νοουμένῳ</span> <span class=\"greek\">ἀμερίστῳ</span>).</p><p class=\"entry-text\">ⓑ Seguido de <span class=\"greek\">ὅτι</span> (BGU 114 I, 9; 2 Km 12:19; EpArist 224; Philo, Virt. 17, Mos. 1, 287; Just. D. 4, 7; 27, 2; B-D-F §397, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:17</a>; 16:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:10</a> D; 1 Cl 27:3; 7:1; Hm 10, 1, 2; Hs 1:3; (com <span class=\"greek\">οἶδα</span>) 2:8.</p><p class=\"entry-text\">ⓒ Seguido de acusativo e infinitivo (2 Macc 14:30; Just. D. 46, 5 <span class=\"greek\">ἃ</span> <span class=\"greek\">πάντως</span> <span class=\"greek\">ἅγια</span> <span class=\"greek\">νοοῦμεν</span> <span class=\"greek\">εἶναι</span>; 49, 22; 60, 3; B-D-F §397, 2; Rob. 1036) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:3</a>; seguido de acusativo e particípio: <span class=\"greek\">ἐνόησα</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">κατηρτισμένους</span>, observei que estais preparados ISm 1:1 (Kaibel 278, 3 <span class=\"greek\">τὸν</span> <span class=\"greek\">φίλον</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">νόει</span>; Just. D. 46, 5 <span class=\"greek\">θεὸν</span> … <span class=\"greek\">ἐντειλάμενον</span> <span class=\"greek\">ὑμῖν</span>).</p><p class=\"entry-text\">ⓓ Seguido de pergunta indireta (IDefixWünsch 4, 56f <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">νοῶσιν</span> <span class=\"greek\">τί</span> <span class=\"greek\">ποιῶσιν</span>; Wsd 4:17; SibOr 3, 796; Just. D. 12, 3) Hm 6, 1, 1; <span class=\"greek\">μὴ</span> <span class=\"greek\">νοῶν</span> <span class=\"greek\">ὅτι</span> (variante <span class=\"greek\">τί</span>) <span class=\"greek\">ἐστίν</span> Hs 5, 4, 2; <span class=\"greek\">οὐ</span> <span class=\"greek\">ν</span>. com pergunta indireta precedente, não compreendo Hm 10, 1, 3. Elipticamente: <span class=\"greek\">πῶς</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">νοῶ</span>, como (isso pode acontecer), não compreendo Hs 5, 6, 1.</p><p class=\"entry-text\">ⓔ Absolutamente (Sir 11:7; TestAbr B 6 p. 110, 22 [Stone p. 68] <span class=\"greek\">καλῶς</span> <span class=\"greek\">ἐνόησας</span>; Just. D. 119, 1 <span class=\"greek\">χάριν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοῆσαι</span>) B 6:10; 17:2; Hs 6, 4, 3b; 9, 28, 6; <span class=\"greek\">νοῆσαί</span> <span class=\"greek\">σε</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">πρῶτον</span>, precisas compreender isto primeiro Hv 3, 8, 11. Compreender, perceber (EpArist 153) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:17</a>. De modo mais completo, <span class=\"greek\">ν</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> (Is 44:18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40</a>.</p><p class=\"entry-text\">② Examinar atentamente, considerar, tomar conhecimento: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀναγινώσκων</span> <span class=\"greek\">νοείτω</span>, que o leitor/leitor público tome nota (destas palavras; ver <span class=\"greek\">ἀναγινώσκω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:14</a>. <span class=\"greek\">νόει</span> <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">λέγω</span>, considera o que digo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:7</a> (Pla., Ep. 8, 352c <span class=\"greek\">νοήσατε</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">λέγω</span>) <span class=\"greek\">ἔτι</span> <span class=\"greek\">κἀκεῖνο</span> <span class=\"greek\">νοεῖτε</span>, considerai também isto 4:14. Com pergunta indireta subsequente 1 Cl 19:3; 8:2.</p><p class=\"entry-text\">③ Formar uma ideia a respeito de algo, pensar, imaginar (En 100:8 <span class=\"greek\">ν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κακόν</span>): <span class=\"greek\">ὑπερεκπερισσοῦ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">νοοῦμεν</span>, muito além do que imaginamos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:20</a>.</p><p class=\"entry-text\">④ Prestar atenção com o propósito de agir adequadamente, ter determinada disposição: <span class=\"greek\">σεμνὰ</span> <span class=\"greek\">ν</span>., ter disposição honrosa 1 Cl 1:3.—DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νόημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (desde Hom.; também LXX; En 5:8; Just.; Ath, 27, 2).</p><p class=\"entry-text\">① Aquilo que se tem em mente como produto de processo intelectual.</p><p class=\"entry-text\">ⓐ Pensamento, em geral (Hom. e outros; Pla., Symp. 197e; SibOr 3, 585): <span class=\"greek\">αἰχμαλωτίζοντες</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπακοὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, levando cativo todo pensamento à obediência a Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:5</a>. Principalmente no plural (Cornutus 16 p. 21, 2; frequentemente em Philo; Herm. Wr. 9, 3): <span class=\"greek\">τ</span>. <span class=\"greek\">καρδίας</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὑμῶν</span>, os vossos corações e pensamentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:7</a> (assim REB) provavelmente pertence aqui, e o mesmo pode aplicar-se a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a>.; 4:4 (mas ver 2 acerca dessas três passagens).</p><p class=\"entry-text\">ⓑ Plano, propósito, intenção (Od. 8, 559; Pla., Pol. 260d), de natureza maléfica (Il. 10, 104; cf. 18, 318; Bar 2:8): os desígnios de Satanás <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:11</a>.</p><p class=\"entry-text\">② Faculdade de processar o pensamento, mente, entendimento (Il. 19, 218 e outros; 3 Macc 5:30), plural: <span class=\"greek\">ἐπωρώθη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">νοήματα</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">ἐτύφλωσεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">νοήματα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀπίστων</span> 4:4. Nessas duas passagens, «mentes» em REB e NRSV. <span class=\"greek\">μή</span> <span class=\"greek\">πως</span> <span class=\"greek\">φθαρῇ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">νοήματα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁπλότητος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Χριστόν</span>, para que vossas mentes não venham a se corromper, afastando-se de vossa sincera dedicação a Cristo 11:3 (REB e NRSV: «pensamentos»). Alguns também incluiriam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:7</a> aqui (NRSV: «mentes»), mas quanto a esta e às duas primeiras passagens, ver 1a.—DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόθος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νόθος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom. e outros; papiros; Wsd 4:3; Philo), relativo a ter nascido fora do matrimônio ou de origem servil e, portanto, sem condição jurídica ou direitos legais, ilegítimo, de nascimento não reconhecido (em oposição a <span class=\"greek\">γνήσιος</span> 1 [q.v.], Menand., Fgm. 248 Kö.; Jos., Ant. 5, 233. A perspectiva antiga não deve ser obscurecida pela sensibilidade moderna). Como metáfora de pessoas que rejeitam a disciplina divina e, por isso (segundo Pr 3:11f), não podem ser filhos de Deus: <span class=\"greek\">ἄρα</span> <span class=\"greek\">νόθοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">υἱοί</span> <span class=\"greek\">ἐστε</span>, portanto sois ilegítimos e não filhos (isto é, sem direitos nem privilégios associados à filiação reconhecida) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:8</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições, papiros, LXX; PsSol 17:40; TestSol 5:5; ApcEsdr 2:11 p. 26, 5 Tdf.; ApcEl [PSI I, 7 verso, 3] «rebanho»; ApcrEzk P1, verso 4; EpArist 112; Philo; Jos., Ant. 2, 18; 17, 249), em geral «lugar de pastoreio» ou «terra de pastagem» (Soph., Hdt., X., Plut., papiros) e frequentemente relativo ao alimento ou à oportunidade de forragear (Pla., Aristot.; 1 Ch 4:40) que esse terreno proporciona.—Em nossa literatura, a palavra se emprega apenas em linguagem figurada.</p><p class=\"entry-text\">① Pastagem de alguém que segue Jesus: <span class=\"greek\">ν</span>. <span class=\"greek\">εὑρίσκειν</span>, encontrar pastagem (literalmente dos rebanhos famintos 1 Ch 4:40; figuradamente de líderes comparados a carneiros que não encontram alimento La 1:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:9</a>. Acerca do sustento espiritual providenciado por Deus como Pastor do povo (isto é, os cristãos); estes são chamados <span class=\"greek\">πρόβατα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νομῆς</span> <span class=\"greek\">σου</span>, ovelhas da tua pastagem (Ps 73:1; 78:13; cf. 99:3) 1 Cl 59:4; semelhantemente 16:5, numa citação de documento desconhecido (talvez En 89:56, 66f), chamado <span class=\"greek\">γραφή</span>.</p><p class=\"entry-text\">② Algo destrutivo que se difunde vorazmente, propagação (a partir do espalhamento de um rebanho no pasto; por exemplo o fogo: Polyb. 1, 48, 5; <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">λαμβανει</span> <span class=\"greek\">νομήν</span> 11, 4 [5], 4; Philo, Aet. M. 127 [conjectura de Usener]), em comparação médica, difundir-se como uma úlcera (desde Hippocr.; Polyb. 1, 81, 6 <span class=\"greek\">νομὴν</span> <span class=\"greek\">ποιεῖται</span> <span class=\"greek\">ἕλκος</span>; Memnon Hist. [I b.c./I a.d.]: 434 Fgm. 1, 2, 4 Jac. [úlcera]; cf. Jos., Bell. 6, 164, partes do complexo do templo comparadas a partes do corpo enfermas): <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">γάγγραινα</span> <span class=\"greek\">νομὴν</span> <span class=\"greek\">ἕξει</span>, o ensino deles se espalhará como um câncer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:17</a>.—DELG s.v. <span class=\"greek\">νέμω</span> Ia. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομίζω</span>, imperfeito <span class=\"greek\">ἐνόμιζον</span>; 1º aoristo <span class=\"greek\">ἐνόμισα</span>; perfeito <span class=\"greek\">νενόμικα</span> (Just., D. 8, 4). Passivo: imperfeito <span class=\"greek\">ἐνομιζόμην</span>; aoristo <span class=\"greek\">ἐνομίσθην</span> (Just.); perfeito <span class=\"greek\">νενόμισμαι</span> (Ar.); (Aeschyl., Hdt. e posteriores; SIG 47, 25 [início do V b.c.]).</p><p class=\"entry-text\">① Seguir ou praticar aquilo que é costumeiro, ter em uso comum (cf. sentido primário [diferentemente GShipp, Nomos ‘Law’ ’78: o sentido de «lei» é anterior ao de «costume»] de <span class=\"greek\">νόμος</span>, q.v., início, como aquilo que é estabelecido pelo uso ou posse). Passivo: ser o costume (Aeschyl., Hdt.; Diod S 10, 3, 4 [<span class=\"greek\">τὰ</span> <span class=\"greek\">νομιζόμενα</span>]; Joseph.; Just., D. 8, 4; inscrições, papiros): <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐνομίζετο</span> <span class=\"greek\">προσευχὴ</span> <span class=\"greek\">εἶναι</span>, onde, segundo o costume, havia um lugar de oração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:13</a> v.l.</p><p class=\"entry-text\">② Formar uma ideia a respeito de algo, mas com certa sugestão de provisoriedade ou de abstenção de afirmação definitiva, pensar, crer, julgar, considerar (Aeschyl., Hdt.; inscrições, papiros, LXX, EpArist, Philo; Jos., Ant. 1, 196), seguido de acusativo e infinitivo (X., An. 6, 1, 29, Cyr. 1, 4, 5; inscrições [índice SIG]; 4 Macc 4:13; 5:16, 18, 19; 9:4; Philo, Congr. Erud. Gr. 139; Ar. 4, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:25</a>; 14:19; 16:27; 17:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:5</a>. <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐνομίζομεν</span> <span class=\"greek\">προσευχὴν</span> <span class=\"greek\">εἶναι</span>, onde supúnhamos que houvesse lugar de oração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:13</a>. <span class=\"greek\">βράδιον</span> <span class=\"greek\">νομίζομεν</span> <span class=\"greek\">ἐπιστροφήν</span> <span class=\"greek\">πεποιῆσθαι</span> <span class=\"greek\">περί</span>, julgamos ter demorado um pouco a tratar dos assuntos (em disputa entre vós) 1 Cl 1:1; <span class=\"greek\">μέγα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαυμαστὸν</span> <span class=\"greek\">νομίζομεν</span> <span class=\"greek\">εἶναι</span>, <span class=\"greek\">εἰ</span> 26:1; 44:3; Dg 4:1, 6. Com duplo acusativo: <span class=\"greek\">οὓς</span> … <span class=\"greek\">νομίζετε</span> <span class=\"greek\">θεούς</span>, aqueles a quem reverenciais como deuses Dg 2:1. (Esta passagem e as abaixo enumeradas com uso passivo poderiam ser colocadas em 1 acima, pois o que é percebido em comum com outros se reflete na tradição e na prática comuns; cf. WFahr, <span class=\"greek\">Θεοὺς</span> <span class=\"greek\">νομίζειν</span> ’70). Seguido de infinitivo (inscrições [índice SIG]; PTebt 50, 11 [112/111b.c.]; PLips 105, 2; 2 Macc 4:32; Just., D. 18, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:36</a>; Dg 2:7; 12:6. Seguido de <span class=\"greek\">ὅτι</span> (X., Hell. 5, 4, 62; Lucian, Syr. Dea 28 p. 474; PFay 109, 4 [I a.d.]; BGU 248, 29 [c. 75 a.d.]; TestJud 5:3; ParJer 5:24; ApcMos 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17</a> <span class=\"greek\">μὴ</span> <span class=\"greek\">νομίσητε</span> (como 4 Macc 2:14; Jos., Ant. 5, 109; Just., A I, 36, 1 [com acusativo e infinitivo]; cf. Just. D. 138, 2 <span class=\"greek\">μὴ</span> <span class=\"greek\">νομίζητε</span> <span class=\"greek\">ὅτι</span>); 10:34; 20:10; GPt 5:18. Com acusativo e <span class=\"greek\">ὅτι</span> subsequente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:29</a> (TestAbr A 14 p. 94, 28 [Stone p. 36]).—Passivo (Appian, Iber. 18 §68; 2 Macc 8:35; EpArist 128; Philo, Spec. Leg. 2, 122; Just., A I, 26, 2 <span class=\"greek\">ὅς</span> … <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐνομίσθη</span>) Dg 1. <span class=\"greek\">ὢν</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐνομίζετο</span> <span class=\"greek\">Ἰωσήφ</span>, sendo filho de José, segundo a opinião corrente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:23</a> (<span class=\"greek\">ὡς</span> <span class=\"greek\">ἐνομίζετο</span> como em Appian, Mithrid. 63 §263, de estimativa monetária; cf. também Appian, Liby. 111 §525 acerca do rei macedônio <span class=\"greek\">τὸν</span> <span class=\"greek\">νομιζόμενον</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">Περσέως</span>, Bell. Civ. 1, 33 §146; 2, 39 §153 <span class=\"greek\">νομιζόμενος</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">Ποσειδῶνος</span>; Paus. 2, 10, 3 <span class=\"greek\">Ἄρατον</span> <span class=\"greek\">Ἀσκληπιοῦ</span> <span class=\"greek\">παῖδα</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">νομίζουσιν</span>; Olympiodorus, Life of Plato, ed. AWestermann 1850 p. 1, 4: <span class=\"greek\">λέγεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Πλάτων</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">Ἀρίστωνος</span>, embora o autor afirme que ele possuía origem transcendente).—B. 1204. Schmidt, Syn. I 333–47. DELG s.v. <span class=\"greek\">νέμω</span> Ic. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo e substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">νόμος</span>; Pla., Aristot. e outros; inscrições [Hatch 134ff]; papiros, por exemplo PMich XIII 659, 319; 668, 9 [ambos VI a.d.] e outros; 4 Macc 5:4; SibOr 8, 112; Mel., P. 94, 713 <span class=\"greek\">ἐν</span> <span class=\"greek\">πόλει</span> <span class=\"greek\">νομικῇ</span>).</p><p class=\"entry-text\">① Relativo a matérias da lei, acerca da lei (<span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">προφητικαῖς</span> <span class=\"greek\">γραφαῖς</span> Orig., C. Cels. 2, 76, 9): <span class=\"greek\">μάχαι</span> <span class=\"greek\">ν</span>., contendas acerca da lei (isto é, da validade da lei [mosaica?]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:9</a> (cf. Philostrat., Vitae Sophist. 1, 22, 1 <span class=\"greek\">ἀγῶνες</span> <span class=\"greek\">ν</span>.).</p><p class=\"entry-text\">② Relativo a estar bem informado acerca da lei, instruído na lei, por isso, como substantivo, <span class=\"greek\">ὁ</span> <span class=\"greek\">νομικός</span>, especialista em direito, jurista, advogado (Strabo 12, 2, 9; Epict. 2, 13, 6–8; IMagnMai 191, 4 [ver Thieme 37]; outros exemplos de inscrições em LRobert, Hellenica I 62, 9; BGU 326 II, 22; 361 III, 2; POxy 237 VIII, 2; CPR I, 18, 24 e outros em papiros; 4 Macc 5:4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:13</a> menciona certo Zenas, o <span class=\"greek\">ν</span>., mas não está claro se era especialista na lei mosaica ou na não mosaica (no segundo caso, muito provavelmente na romana).—Em outras passagens do NT, apenas uma vez em Mt e diversas em Lk, sempre acerca de conhecedores da lei mosaica: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:25</a>. Plural 11:45f, 52; 14:3. Cf. PEg2 2. Mencionados com fariseus 7:30; 11:53 D; 14:3.—Schürer II 320–80, especialmente 324 n. 4; GRuderg, ConNeot II ’36, 41f; Kilpatrick s.v. <span class=\"greek\">γραμματεύς</span>.—B. 1424. New Docs 2, 89. DELG s.v. <span class=\"greek\">νέμω</span> Ic. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμιμος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νόμιμος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">νομίζω</span>; Pind., autores trágicos, Hdt. e outros; inscrições, também IBM III/2, 480, 339f [ver p. 141, cf. <span class=\"greek\">ἔννομος</span>]; papiros, LXX, Just.; Tat. 4, 1), relativo à conformidade com padrões tradicionais ou com a lei, legal. Como substantivo: <span class=\"greek\">τὸ</span> <span class=\"greek\">νόμιμον</span>, sobretudo no plural <span class=\"greek\">τὰ</span> <span class=\"greek\">νόμιμα</span> (Pind. e outros; Diog. L. 7, 119 [os <span class=\"greek\">θεοσεβεῖς</span> são conhecedores de <span class=\"greek\">τῶν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">νομίμων</span> = ritos ou cerimônias habituais relativos a divindades]; inscrições, papiros; Lev 18:26; Pr 3:1 e outros; LXX; EpArist 10; 127; Philo, Mos. 2, 12ff e outros; Jos., Ant. 8, 129; 18, 344, Vi. 191; Just., D. 29, 3; 42, 3; 67, 5; Tat. 4:1), estatutos, leis, mandamentos: <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">προσταγμάτων</span> <span class=\"greek\">αὐτοῦ</span>, andar de acordo com as leis dos mandamentos de Deus 1 Cl 3:4 (cf. Jer 33:4; Ezk 5:6f). <span class=\"greek\">τοῖς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δεσπότου</span> <span class=\"greek\">ἀκολουθεῖν</span>, seguir as prescrições do Senhor 40:4. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πορεύεσθαι</span>, andar segundo os estatutos de Deus 1:3 (os manuscritos apresentam <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">νόμοις</span>; a leitura <span class=\"greek\">νομίμοις</span>, encontrada em Clem. de Al., Strom. 4, 17, 105, foi adotada pelas edições mais recentes). <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, guardar os mandamentos de Deus Hv 1, 3, 4 (Eur., Suppl. 19 <span class=\"greek\">ν</span>. <span class=\"greek\">θεῶν</span>).—DELG s.v. <span class=\"greek\">νέμω</span> Ic. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομίμως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομίμως</span>, advérbio de <span class=\"greek\">νόμιμος</span> (desde Thu. 2, 74, 3; OGI 669, 19; 24; frequente em papiros; 4 Macc 6:18; SibOr 11, 82; Jos., C. Ap. 2. 152; 217; Ath., R. 23 p. 76, 5), relativo à conformidade com o procedimento usual, segundo a(s) regra(s)/lei (cf. Lysias Fgm. 53, 4 <span class=\"greek\">ν</span>. <span class=\"greek\">ἀποθανεῖν</span> = morrer conforme a experiência humana normal). De atletas, <span class=\"greek\">ν</span>. <span class=\"greek\">ἀθλεῖν</span>, competir de acordo com as regras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:5</a> (talvez em contraposição à condição de devidamente habilitado, cf. Epict. 3, 10, 8 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">σοι</span> <span class=\"greek\">λέγει</span> ‘<span class=\"greek\">δός</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἀπόδειξιν</span>, <span class=\"greek\">εἰ</span> <span class=\"greek\">νομίμως</span> <span class=\"greek\">ἤθλησας</span>’). Jogo de palavras: <span class=\"greek\">καλὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span>, <span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">χρῆται</span>, a lei é boa se alguém a usa legitimamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:8</a> (Rob. 1201).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμισμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νόμισμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">νομίζω</span>; significado primário «qualquer coisa sancionada pelo uso comum»: Aeschyl. e outros), dinheiro oficialmente introduzido no uso comum, moeda (assim em Hdt., Aristoph. e outros; inscrições; PTebt 485 [II b.c.]; PGrenf II, 77, 8; 2 Esdr 17: 72 v.l.; 1 Macc 15:6; EpArist 33; Philo, Spec. Leg. 2, 33; Jos., Bell. 2, 592, Ant. 14, 371): <span class=\"greek\">τὸ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κήνσου</span>, a moeda para pagar o imposto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:19</a> (seguido por Just., A I, 17, 2 <span class=\"greek\">τίνος</span> <span class=\"greek\">εἰκόνα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἔχει</span>;). Plural (Herodian 1, 9, 7), como metáfora (Philo também aprecia esse emprego): <span class=\"greek\">νομίσματα</span> <span class=\"greek\">δύο</span>, <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">μὲν</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">δὲ</span> <span class=\"greek\">κόσμου</span>, duas cunhagens, uma de Deus e outra do mundo, acerca dos crentes e dos descrentes IMg 5:2.—B. 775. DELG s.v. <span class=\"greek\">νέμω</span> Ic. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοδιδάσκαλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομοδιδάσκαλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (ver SEG XLII, 1813 sobre a formação e a proveniência judaica; cf. PvanderHorst BZ 36, ’92, 161–78, especialmente 167f; sobre a restauração problemática em CIJ I, 201 ver GHorsley/JLee, Filología Neotestamentaria 10, ’97, 79; <span class=\"greek\">νομοδιδάκτης</span> em Plut., Cato Maj. 20, 4; Artem. 2, 29.—Synesius apresenta <span class=\"greek\">νομοδιδάσκαλος</span> Ep. 105 p. 248a em sentido geral, e Ep. 4 p. 162a com sentido especificamente judaico), mestre da lei, acerca de pessoas que se afastam do ensino correto: <span class=\"greek\">θέλοντες</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">νομοδιδάσκαλοι</span>, desejam ser mestres da lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:7</a>. As outras duas passagens da nossa literatura referem-se claramente a mestres da lei mosaica: Gamaliel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:34</a>. Com fariseus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:17</a>.—Schürer II 324f. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομοθεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νόμος</span>, <span class=\"greek\">τίθημι</span>), literalmente «ato de dar leis» (Pla., Aristot. e outros; <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Theoph. Ant. 3, 17 [p. 238, 1]), e depois também seu resultado, legislação, conjunto de leis (Diod S 1, 95, 6; 12, 11, 4; Dionys. Hal. 10, 57f; 11, 6; Ps.-Lucian, Am. 22; OGI 326; 26 [II b.c.]; PLips 35, 7; Mitt-Wilck. I/2, 6, 11; Tat., Orig., Hippol. Especificamente sobre a lei mosaica: Philo, 2 Macc 6:23; 4 Macc 5:35; 17:16; EpArist; Aristob. em Eus., PE 8, 10, 13; Philo, Mos. 2, 25; 31 e outros; Jos., Ant. 6, 93 e outros; Just., D. 92, 2), com os outros grandes dons de Deus a Israel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:4</a>.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθετέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομοθετέω</span> (<span class=\"greek\">νόμος</span>, <span class=\"greek\">θέσις</span> [<span class=\"greek\">τίθημι</span>]), futuro <span class=\"greek\">νομοθετήσω</span> LXX; 1º aoristo <span class=\"greek\">ἐνομοθέτησα</span>; perfeito <span class=\"greek\">νενομοθέτηκα</span> (Tat.). Passivo: subjuntivo aoristo, 3ª pessoa do singular; <span class=\"greek\">νομοθετηθῇ</span> Dt 17:10; perfeito <span class=\"greek\">νενομοθέτημαι</span>; particípio <span class=\"greek\">νενομοθετημένος</span> (Lysias, X., Pla. e outros; inscrições, papiros, LXX, EpArist; Aristob. em Eus., PE 8, 10, 12 [Denis p. 219, 36]; Philo, Joseph., Just., Tat., Mel.).</p><p class=\"entry-text\">① Exercer a função de legislador, legislar (sobre Deus, Orig., C. Cels. 5, 37, 2; sobre o Logos: Hippol., Ref. 8, 9, 8; sobre legisladores humanos: Theoph. Ant. 3, 23 [p. 250, 11]), acerca de Moisés (Philo, Mos. 2, 9; Jos., C. Ap. 1, 284f, Ant. 1, 19): <span class=\"greek\">καλῶς</span> <span class=\"greek\">ν</span>. 10:11. Passivo: receber leis: <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῆς</span> (isto é, <span class=\"greek\">τῆς</span> <span class=\"greek\">Λευιτικῆς</span> <span class=\"greek\">ἱερωσύνης</span>) <span class=\"greek\">νενομοθέτηται</span>, com base nela (isto é, no sacerdócio levítico), o povo recebeu a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a> (<span class=\"greek\">νομοθετεῖν</span> <span class=\"greek\">τινα</span> encontra-se apenas em Ps.-Galen [HWagner, Galeni qui fertur libellus <span class=\"greek\">Εἰ</span> <span class=\"greek\">ζῷον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">γαστρός</span>, dissertação Marburg 1914] p. 17, 8 v.l. <span class=\"greek\">ἐνομοθέτησε</span> <span class=\"greek\">Ἀθηναίους</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Πάλλας</span> e em LXX Ps 24:8; 26:11; 118:33. Em outros lugares do grego, <span class=\"greek\">νομοθετεῖν</span> <span class=\"greek\">τινι</span>; mas essa construção também pode produzir um passivo pessoal: Kühner-G. I 124).</p><p class=\"entry-text\">② Estabelecer com fundamento em sanção legal, ordenar, instituir por lei (IAndrosIsis, Kyme 4 [=New Docs 1 p. 18 linha 8]; Tat. 8, 2 <span class=\"greek\">ἀποτμήσεις</span> <span class=\"greek\">αἰδοίων</span>): <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὁρίζοντες</span> <span class=\"greek\">μηδὲ</span> <span class=\"greek\">νομοθετοῦντες</span> GMary 463, 30 (ver <span class=\"greek\">ὁρίζω</span> 2a<span class=\"greek\">α</span>). Passivo (Appian, Bell. Civ. 4, 2 §6 <span class=\"greek\">καινὴν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">νομοθετηθῆναι</span> = nova magistratura será instituída por lei; 4, 7 §27; <span class=\"greek\">νομοθετούμενον</span> <span class=\"greek\">ἦθος</span> Hippol., Ref. 9, 30, 18): <span class=\"greek\">διαθήκη</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κρείττοσιν</span> <span class=\"greek\">ἐπαγγελίαις</span> <span class=\"greek\">νενομοθέτηται</span>, uma aliança que foi legalmente instituída com base em promessas superiores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a> (cf. Philo, Migr. Abr. 91 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">νομοθετηθέντα</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">νενομοθετημένα</span>, aquilo que ele ordenou legalmente (OGI 329, 13 [II b.c.] <span class=\"greek\">τὰ</span> <span class=\"greek\">νενομοθετημένα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλέων</span>.—<span class=\"greek\">τὰ</span> <span class=\"greek\">νομοθετηθέντα</span>: Philo, Spec. Leg. 1, 198 e outros; Jos., Ant. 3, 317 <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span>) 1 Cl 43:1.—Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a>; 8:6 ver HHollander, BT 30, ’79, 244–47.—DELG s.v. <span class=\"greek\">τίθημι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθέτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νομοθέτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">νόμος</span>, <span class=\"greek\">τίθημι</span>; desde Antiphon 5, 15; Thu. 8, 97, 2; Diod S 40, 3, 6 [acerca de <span class=\"greek\">Μωσῆς</span>]; inscrições; Nicol. Dam.: [I b.c.]: 90 Fgm. 72 Jac. [em Jos., Ant. 1, 95]; EpArist, Philo; Jos., Ant. 1, 18; 20; 22 e outros; Just.; Tat. 9, 2; Iren. 5, 26, 2 [Harv. II 397, 7]; na LXX apenas Ps 9:21), legislador (de Jesus: <span class=\"greek\">ν</span>. <span class=\"greek\">χριστιανῶν</span> Orig., C. Cels. 3, 8, 9), de Deus (Dio Chrys. 19 [36], 32; Maximus Tyr. 35, 8d <span class=\"greek\">νομοθέτης</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>; Philo, Sacr. Abel. 131, Op. M. 61; cf. Orig., C. Cels. 1, 26, 5. Em IAndrosIsis, Kyme p. 122, 4 [=New Docs 1, p. 18 linha 8f], Ísis diz: <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">νόμους</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">ἐθέμην</span>| <span class=\"greek\">κ</span>. <span class=\"greek\">ἐνομοθέτησα</span>. Ver também Theoph. Ant. 3, 9 [p. 222, 17]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:12</a>. <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">γίνεσθε</span> <span class=\"greek\">νομοθέται</span> <span class=\"greek\">ἀγαθοί</span>, tornai-vos vossos próprios bons legisladores 21:4 (cf. Diod S 20, 70, 4 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">νομοθέτης</span>; Just., D. 18, 3 <span class=\"greek\">ὁ</span> <span class=\"greek\">καινὸς</span> <span class=\"greek\">ν</span>. [Cristo]).—DELG s.v. <span class=\"greek\">τίθημι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νόμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">νέμω</span>; [Zenodotus lê <span class=\"greek\">ν</span>. em Od. 1, 3] desde Hes.; empréstimo no rabínico.—Sobre a história da palavra: MPohlenz, Nomos: Philol 97, ’48, 135–42; GShipp, Nomos ‘Law’ ’78; MOstwald, Nomos and the Beginnings of Athenian Democracy ’69). O sentido primário relaciona-se àquilo que é concebido como padrão ou regras de conduta civilizada geralmente reconhecidas, especialmente sancionadas pela tradição (Pind., Fgm. 152, 1=169 Schr. <span class=\"greek\">νόμος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">βασιλεύς</span>; cf. SEG XVII, 755, 16: Domiciano se preocupa com práticas opressivas que se consolidam como «costume»; MGigante, <span class=\"greek\">ΝΟΜΟΣ</span> <span class=\"greek\">ΒΑΣΙΛΕΥΣ</span> [Richerche filologiche 1] ’56). O sinônimo <span class=\"greek\">ἔθος</span> (cf. <span class=\"greek\">συνήθεια</span>) designa o que é habitual ou costumeiro, especialmente quanto ao comportamento pessoal. Além das regras que se estabelecem por tradição, o Estado ou outro órgão legislativo pode promulgar disposições reconhecidas por todos os envolvidos e que, por sua vez, passam a integrar a tradição jurídica. Um problema semântico especial para leitores modernos do termo <span class=\"greek\">ν</span>. é a tendência geral de restringir «lei» a estatutos codificados. Essa limitação levou a muitos debates infrutíferos na história da interpretação do NT.—HRemus, Sciences Religieuses/Studies in Religion 13, ’84, 5–18; ASegal, Torah and Nomos in Recent Scholarly Discussion, ibid., 19–27.</p><p class=\"entry-text\">① Procedimento ou prática que se estabeleceu, costume, regra, princípio, norma (Alcman [VII b.c.], Fgm. 93 D2, sobre o canto que a ave entoa; Ocellus [II b.c.] c. 49 Harder [1926] <span class=\"greek\">τῆς</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">νόμος</span>; Appian, Basil. 1 §2 <span class=\"greek\">πολέμου</span> <span class=\"greek\">ν</span>., Bell. Civ. 5, 44 §186 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦδε</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">νόμου</span> = sob esta tua regra que governa o comportamento; Polyaenus 5, 5, 3 <span class=\"greek\">ν</span>. <span class=\"greek\">πόμπης</span>; 7, 11, 6 <span class=\"greek\">ν</span>. <span class=\"greek\">φιλίας</span>; Sextus 123 <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">νόμος</span>; Just., A II, 2, 4 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">ν</span>.; Ath. 3, 1 <span class=\"greek\">νόμῳ</span> <span class=\"greek\">φύσεως</span>; 13, 1 <span class=\"greek\">θυσιῶν</span> <span class=\"greek\">νόμῳ</span>).</p><p class=\"entry-text\">ⓐ Em geral: <span class=\"greek\">κατὰ</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">ἐντολῆς</span> <span class=\"greek\">σαρκίνης</span>, conforme a regra de um mandamento exterior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:16</a>. <span class=\"greek\">εὑρίσκω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>, observo um procedimento, princípio ou sistema estabelecido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:21</a> (<span class=\"greek\">ν</span>. como «princípio», isto é, uma ordem não escrita das coisas, Soph., Ant. 908). Segundo Bauer, Paulo emprega a expressão <span class=\"greek\">νόμος</span> (que domina o contexto) em casos nos quais provavelmente teria preferido outra palavra. Mas também é provável que Paulo produza deliberadamente um jogo verbal para acentuar a situação difícil daqueles que não confiam no evangelho da libertação do constrangimento jurídico: o apóstolo fala de um princípio que obriga a observar um código de comportamento que qualquer pessoa sensata reconheceria como correto e válido: <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νοός</span> <span class=\"greek\">μου</span>, a lei da minha mente, versículo 23b (ver <span class=\"greek\">νοῦς</span> 1a). Em luta amarga com esse <span class=\"greek\">νόμος</span> está um <span class=\"greek\">ἕτερος</span> <span class=\"greek\">νόμος</span> que, ao contrário do <span class=\"greek\">νοῦς</span>, habita <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μέλεσίν</span> <span class=\"greek\">μου</span>, nos membros (físicos) do meu corpo, versículo 23a, e por isso é um <span class=\"greek\">νόμος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁμαρτίας</span>, lei do pecado, versículos 23c e 25b, ou um <span class=\"greek\">νόμος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θανάτου</span> 8:2b. Esse sentido prepara o caminho para a perspectiva particular seguinte.</p><p class=\"entry-text\">ⓑ Da vida sob o senhorio de Jesus Cristo como «nova lei» ou «sistema» de conduta que constitui tradição não escrita: <span class=\"greek\">ὁ</span> <span class=\"greek\">καινὸς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> 2:6; de forma abreviada <span class=\"greek\">ν</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> IMg 2 (cf. Just., D. 11, 4; 43, 1; Mel., P. 7, 46). Os primórdios dessa terminologia remontam a Paulo: <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> = o padrão estabelecido por Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:2</a> (como sugere o versículo 3, Cristo permitiu ser reduzido a nada, estabelecendo assim o padrão para que ninguém se considere alguma coisa). O evangelho é um <span class=\"greek\">νόμος</span> <span class=\"greek\">πίστεως</span>, lei ou sistema que requer fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>b (FGerhard, TZ 10, ’54, 401–17), ou <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰ</span>., a lei do espírito (= código do espírito) da vida em Cristo Jesus 8:2a. No mesmo sentido, Js fala de um <span class=\"greek\">ν</span>. <span class=\"greek\">βασιλικός</span> (ver <span class=\"greek\">βασιλικός</span>) 2:8 ou <span class=\"greek\">ν</span>. <span class=\"greek\">ἐλευθερίας</span>, lei da liberdade, versículo 12 (<span class=\"greek\">λόγος</span> <span class=\"greek\">ἐλ</span>. P74), <span class=\"greek\">ν</span>. <span class=\"greek\">τέλειος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλευθερίας</span> 1:25 (a associação com 1QS 10:6, 8, 11 feita por EStauffer, TLZ 77, ’52, 527–32, é rejeitada por SNötscher, Biblica 34, ’53, 193f. Sobre a prática moral espontânea, cf. Pind., Fgm. 152 [169 Schr.] 1f <span class=\"greek\">νόμος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">βασιλεὺς</span> | <span class=\"greek\">θνατῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀθανάτων</span> | <span class=\"greek\">ἄγει</span> <span class=\"greek\">δικαιῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βιαιότατον</span>| <span class=\"greek\">ὑπερτάτᾳ</span> <span class=\"greek\">χειρί</span> = o costume é senhor de todos, mortais e imortais, e com mão forte governa o poder supremo dos justos. Plut., Mor. 780c interpreta o uso pindárico de <span class=\"greek\">νόμος</span>: «não escrito externamente em livros ou tabuinhas de madeira, mas como razão viva em atuação dentro dele», <span class=\"greek\">ἔμψυχος</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">λόγῳ</span>; Aristot., EN 4, 8, 10 <span class=\"greek\">οἷον</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὢν</span> <span class=\"greek\">ἑαυτῷ</span>; Diod S 1, 94, 1 <span class=\"greek\">ν</span>. <span class=\"greek\">ἔγγραπτος</span>; cf. também Ovid, Met. 1, 90 sponte sua sine lege fidem rectumque colebat; Mayor, comm. «Notes» 73.—RHirzel, <span class=\"greek\">ΑΓΡΑΦΟΣ</span> <span class=\"greek\">ΝΟΜΟΣ</span> 1903.). Alguns incluiriam <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:9</a> aqui (ver LAllevi, Scuola Cattol. 67, ’39, 529–42), mas ver 2b adiante.—Hermas também, que em parte interpreta a tradição jurídica de Israel como referente aos cristãos, considera o evangelho, manifestado na vida e nas palavras de Cristo, a expressão suprema da vontade ou «lei» de Deus. Ele diz de Cristo: <span class=\"greek\">δοὺς</span> <span class=\"greek\">αὐτοῖς</span> (isto é, os crentes) <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>., <span class=\"greek\">ὅν</span> <span class=\"greek\">ἔλαβε</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">αὐτοῦ</span> Hs 5, 6, 3; cf. Hs 8, 3, 3. Ou vê no <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κηρυχθεὶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πέρατα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, isto é, na pregação acerca do Filho de Deus até os confins da terra, o <span class=\"greek\">νόμος</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δοθεὶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅλον</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμον</span> 8, 3, 2. Devem entender-se de modo semelhante: <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. 8, 3, 4. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">παθεῖν</span> 8, 3, 6. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">θλίβεσθαι</span> 8, 3, 7. <span class=\"greek\">ἀρνησάμενοι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>, no mesmo lugar; <span class=\"greek\">βλασφημεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. 8, 6, 2.</p><p class=\"entry-text\">② Sistema jurídico constitucional ou estatutário, lei.</p><p class=\"entry-text\">ⓐ Em geral: segundo que tipo de lei? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, a lei da cidade aplicada pelo governante da cidade (<span class=\"greek\">ν</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πόλεσι</span> <span class=\"greek\">γραπτός</span> Orig., C. Cels. 5, 37, 2); a penalidade por violá-la é o banimento Hs 1:5f. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">χρῆσθαι</span>, observar as leis 1:3; <span class=\"greek\">πείθεσθαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὡρισμένοις</span> <span class=\"greek\">ν</span>., obedecer às leis estabelecidas Dg 5:10; <span class=\"greek\">νικᾶν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ν</span>., superar as leis, no mesmo lugar (<span class=\"greek\">νικάω</span> 3). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:1</a>f, bem como as sentenças gerais de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:15</a>b e 5:13b, foram considerados por alguns (por exemplo BWeiss, Jülicher) referentes ao direito romano, mas é mais provável que se refiram à lei mosaica (ver 3 abaixo).</p><p class=\"entry-text\">ⓑ Especificamente: a lei que Moisés recebeu de Deus e que constitui o padrão pelo qual se determina a pertença ao povo de Israel (Diod S 1, 94, 1; 2: o legislador Mneves recebe a lei de Hermes, Minos de Zeus, Licurgo de Apolo, Zaratustra do <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">δαίμων</span>, Zalmoxis de Héstia; <span class=\"greek\">παρὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Ἰουδαίοις</span>, <span class=\"greek\">Μωϋσῆς</span> recebe a lei do <span class=\"greek\">Ἰαὼ</span> <span class=\"greek\">ἐπικαλούμενος</span> <span class=\"greek\">θεός</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">Μωϋσέως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:5</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">Μωϋσέως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:28</a>. Também <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:23</a>f, 39; GJs 14:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (Theoph. Ant. 2, 14 [p. 136, 4]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:6</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:7</a> (cf. Tat. 7, 2; 32, 1; Ath. 3:2). <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἡμῶν</span>, <span class=\"greek\">ὑμῶν</span>, <span class=\"greek\">αὐτῶν</span> etc. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:31</a>; 19:7b v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:8</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἡμέτερον</span> <span class=\"greek\">ν</span>. 24:6 v.l. (cf. Jos., Ant. 7, 131). <span class=\"greek\">ὁ</span> <span class=\"greek\">πατρῷος</span> <span class=\"greek\">ν</span>. 22:3. <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐντολῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:15</a>. Como o contexto de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:29</a> <span class=\"greek\">ἐγκαλούμενον</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ζητημάτων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">αὐτῶν</span> aponta para a ligação íntima entre crença, culto e solidariedade comunitária na tradição judaica, traduz-se melhor <span class=\"greek\">νόμος</span> como uma hendíade: (acusado em questões) relativas à crença e aos costumes deles; cf. <span class=\"greek\">ν</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὑμᾶς</span> 18:15. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:31</a> (CRhyne, <span class=\"greek\">Νόμος</span> <span class=\"greek\">Δικαιοσύνης</span> and the meaning of <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:4</a>: CBQ 47, ’85, 486–99).—De modo absoluto, sem qualificação adicional: <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:36</a>; 23:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:13</a>; 7:53; 21:20, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:15</a> (<span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, a obra da lei [= resultado moral exigido pelo código mosaico] está escrita no coração; de modo diferente, Diod S 1, 94, 1 <span class=\"greek\">ν</span>. <span class=\"greek\">ἔγγραπτος</span>, ver 1b acima), 18, 20, 23b, 26; 4:15a, 16; 7:1b, 4–7, 12, 14, 16; 8:3f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.56\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:12</a>f, 17, 19, 21a, 24; 5:3, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:8</a> (GRudberg, ConNeot 7, ’42, 15); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:19</a> (ver Windisch, Hdb. excursus ad loc.), 28a; 10:1; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:9</a> (ver 1b acima); <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:28</a>b; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19</a>; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>., conforme a lei (mosaica) (Jos., Ant. 14, 173; 15, 51 e outros; Just., D. 10, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:7</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:12</a>; 23:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>; 9:22. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νόμον</span>, contra a lei (Jos., Ant. 17, 151, C. Ap. 2, 219; Ath. 1, 3 <span class=\"greek\">παρὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ν</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:13</a>.—<span class=\"greek\">νόμος</span> sem artigo no mesmo sentido (sobre a tentativa, desde Origen, In Ep. ad <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:7</a> ed. Lomm. VI 201, de estabelecer diferença de sentido entre o uso paulino de <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> e <span class=\"greek\">νόμος</span>, ver B-D-F §258, 2; Rob. 796; Mlt-Turner 177; Grafe [ver 3b abaixo] 7–11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:13</a>ab, 17, 23a, *25a; 3:31ab; 5:13, 20; 7:1a (ver acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:19</a>b; 5:23 (JRobb, ET 56, ’45, 279f compara <span class=\"greek\">κατὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τοιούτων</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστι</span> <span class=\"greek\">νόμος</span> Aristot., Pol. 1284a). <span class=\"greek\">δικαίῳ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κεῖται</span>, <span class=\"greek\">ἀνόμοις</span> <span class=\"greek\">δὲ</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:9</a>. Cf. <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">νόμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:14</a> (em Pla., Pol. e no pensamento estoico, a pessoa sábia não necessitava de mandamento [Stoic. III 519], mas a má necessitava; MPohlenz, Stoa ’48/49 I 133; II 75). Empregado com preposições: <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:18</a>, 21c (v.l. <span class=\"greek\">ἐν</span> <span class=\"greek\">ν</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:9</a> (<span class=\"greek\">ἐκ</span> <span class=\"greek\">νόμου</span> pode também significar «segundo» ou «em conformidade com a lei»: PRev 15, 11 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">νόμων</span>); cf. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:5</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">νόμου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:12</a>b; 3:20b; 4:13; 7:7b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:19</a>a, 21; <span class=\"greek\">ἐν</span> <span class=\"greek\">ν</span>. (<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. Iren. 3, 11, 8 [Harv. II 49, 9]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:12</a>a, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:11</a>, 21c v.l.; 5:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:6</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">νόμον</span> 3:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:4</a>; 10:8 (fazer uma oferta <span class=\"greek\">κατὰ</span> <span class=\"greek\">νόμον</span> como Arrian, Anab. 2, 26, 4; 5, 8, 2); <span class=\"greek\">χωρὶς</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:21</a>a; 7:8f; <span class=\"greek\">ἄχρι</span> <span class=\"greek\">ν</span>. 5:13a. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">νόμον</span> 6:14f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:23</a>; 4:4f, 21a; 5:18 (cf. Just., D. 45, 3 <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>.).—Dependendo de substantivo sem artigo: <span class=\"greek\">παραβάτης</span> <span class=\"greek\">νόμου</span>, transgressor da lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:25</a>b (27b com artigo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:11</a>. <span class=\"greek\">ποιητὴς</span> <span class=\"greek\">ν</span>., observador da lei 4:11d (com artigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:13</a>b). <span class=\"greek\">τέλος</span> <span class=\"greek\">ν</span>., fim da lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:4</a> (RBultmann e HSchlier, Christus des Ges. Ende ’40). <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">ν</span>., cumprimento da lei 13:10. <span class=\"greek\">ν</span>. <span class=\"greek\">μετάθεσις</span>, mudança na lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:12</a>. <span class=\"greek\">ἔργα</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:20</a>a, 28; 9:32 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:16</a>; 3:2, 5, 10a.—(<span class=\"greek\">ὁ</span>) <span class=\"greek\">ν</span>. (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:22</a>, 25a; 8:7, pois foi dada por Deus e corresponde à sua vontade. Duradoura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:17</a> (cf. Bar 4:1; PsSol 10:4; Philo, Mos. 2, 14; Jos., C. Ap. 2, 277).—Com verbos, com ou sem artigo: <span class=\"greek\">ν</span>. <span class=\"greek\">ἔχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:7</a>a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:14</a> (ApcSed 14:5). <span class=\"greek\">πληροῦν</span> <span class=\"greek\">ν</span>., cumprir a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:8</a>; passivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a> (Mel., P. 42, 291). <span class=\"greek\">πληροῦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δικαίωμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>., cumprir a exigência da lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4</a>. <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>., observar a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:13</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">δικαιώματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">φυλάσσειν</span>, observar os preceitos da lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:26</a>; <span class=\"greek\">διώκειν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">δικαιοσύνης</span> 9:31a; <span class=\"greek\">πράσσειν</span> <span class=\"greek\">ν</span>. 2:25a. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:19</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:14</a>b, ver abaixo; <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τηρεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:10</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τελεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:27</a>. <span class=\"greek\">φθάνειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ν</span>. 9:31b. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">Ἰουδαϊσμὸν</span> <span class=\"greek\">ζῆν</span> IMg 8:1 v.l. é provavelmente erro textual (Pearson, Lghtf., Funk, Bihlmeyer, Hilgenfeld; Zahn, Ign. v. Ant. 1873 p. 354, 1 [diferentemente na edição de Zahn] omitem todos <span class=\"greek\">νόμον</span> como glosa e são apoiados pelas versões latinas; ver Hdb. ad loc.). <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ποιεῖν</span>, cumprir as exigências da lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:14</a>b (ApcSed 14:5; FFlückiger, TZ 8, ’52, 17–42). <span class=\"greek\">καταλαλεῖν</span> <span class=\"greek\">νόμου</span>, <span class=\"greek\">κρίνειν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:11</a>abc. <span class=\"greek\">ἐδόθη</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:21</a>a.—Plural: <span class=\"greek\">διδοὺς</span> <span class=\"greek\">νόμους</span> <span class=\"greek\">μου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:10</a>; cf. 10:16 (ambos Jer 38:33).—De uma disposição particular da lei: <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνδρός</span>, a lei naquilo que diz respeito ao marido (Aristot., Fgm. 184 R. <span class=\"greek\">νόμοι</span> <span class=\"greek\">ἀνδρὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γαμετῆς</span>.—SIG 1198, 14 <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐρανιστῶν</span>; Num 9:12 <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span>; Philo, Sobr. 49 <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">λέπρας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:2</a>b; cf. 7:3 e <span class=\"greek\">δέδεται</span> <span class=\"greek\">νόμῳ</span>, versículo 2a (sobre a imagem, Straub 94f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:39</a> v.l.—A lei é, por assim dizer, personificada (Demosth. 43, 59; Aeschin. 1, 18; Herm. Wr. 12, 4 [a lei da punição]; IMagnMai 92a, 11 <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">συντάσσει</span>; b, 16 <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἀγορεύει</span>; Jos., Ant. 3, 274) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19</a>.</p><p class=\"entry-text\">③ Coleção de escritos sagrados preciosos para o povo de Deus, legislação sagrada.</p><p class=\"entry-text\">ⓐ Em sentido estrito, a lei = o Pentateuco, a obra de Moisés legislador (Diod S 40, 3, 6 <span class=\"greek\">προσγέγραπται</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">νόμοις</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τελευτῆς</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">Μωσῆς</span> <span class=\"greek\">ἀκούσας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τάδε</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰουδαίοις</span> = ao fim das leis acrescenta-se: eis o que Moisés ouviu de Deus e está dizendo aos judeus. <span class=\"greek\">ὁ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">μεταξὺ</span> <span class=\"greek\">καθαρῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀκαθάρτων</span> <span class=\"greek\">διαστείλας</span> <span class=\"greek\">θεός</span> Iren. 3, 12, 7 [Harv. II 60, 3]; cf. Hippol., Ref. 7, 34, 1): <span class=\"greek\">τὸ</span> <span class=\"greek\">βιβλίον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, o livro da lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:10</a>b (cf. Dt 27:26). Também simplesmente <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> (Jos., Bell. 7, 162 <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>., ou 2, 229 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱερὸς</span> <span class=\"greek\">ν</span>., acerca do livro sagrado em sentido concreto) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:5</a> (refere-se a Num 28:9f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:8</a> (cf. Dt 25:4); 14:34 (cf. Gen 3:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:21</a>b (a história de Abraão); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:19</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑμέτερος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:17</a> (cf. Jos., Bell. 5, 402; Tat. 40, 1 <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἡμετέρους</span> <span class=\"greek\">ν</span>.). <span class=\"greek\">ἐν</span> <span class=\"greek\">Μωϋσέως</span> <span class=\"greek\">νόμῳ</span> <span class=\"greek\">γέγραπται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:9</a>. <span class=\"greek\">καθὼς</span> <span class=\"greek\">γέγραπται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">νόμῳ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:23</a> (<span class=\"greek\">γέγραπται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">νόμῳ</span> como em Athen. 6, 27, 23c; IMagnMai 52, 35 [III b.c.]; Mel., P. 11, 71; cf. Just., D. 8, 4 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">γεγραμμένα</span>); cf. versículo 24. <span class=\"greek\">ἔγραψεν</span> <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νόμῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:45</a> (cf. Cercidas [III b.c.], Fgm. 1, 18f Diehl2 [=Coll. Alex. p. 204, 29=Knox p. 196] <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦθ</span>’ <span class=\"greek\">Ὅμηρος</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἰλιάδι</span>).—As Escrituras Sagradas (AT) referidas em sua totalidade na expressão <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span> (Orig., C. Cels. 2, 6, 4; cf. Hippol., Ref. 8, 19, 1), a lei (<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">הַתּוֹרָה</span>) e os profetas (<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">הַנְּבִיאִים</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17</a>; 7:12; 11:13; 22:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:15</a>; 24:14; 28:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:21</a>b; cf. Dg 11:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:45</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">γεγραμμένα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">Μωϋσέως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">προφήταις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ψαλμοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:44</a>.</p><p class=\"entry-text\">ⓑ Em sentido mais amplo = Escritura Sagrada em geral, com base no princípio de a parte de maior autoridade emprestar seu nome ao todo (<span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Theoph. Ant. 1, 11 [p. 82, 15]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:34</a> (Ps 81:6); 12:34 (Ps 109:4; Is 9:6; Da 7:14); 15:25 (Ps 34:19; 68:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:21</a> (Is 28:11f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19</a> (precedido por um conjunto de citações dos Salmos e dos profetas).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:26</a>; 16:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:49</a>.—JHänel, Der Schriftbegriff Jesu 1919; OMichel, Pls u. s. Bibel 1929; SWesterholm, Studies in Religion 15, ’86, 327–36.—JMeinhold, Jesus u. das AT 1896; MKähler, Jesus u. das AT2 1896; AKlöpper, Z. Stellung Jesu gegenüber d. Mos. Gesetz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17</a>–48: ZWT 39, 1896, 1–23; EKlostermann, Jesu Stellung z. AT 1904; AvHarnack, Hat Jesus das atl. Gesetz abgeschafft?: Aus Wissenschaft u. Leben II 1911, 225–36, SBBerlAk 1912, 184–207; KBenz, D. Stellung Jesu zum atl. Gesetz 1914; MGoguel, RHPR 7, 1927, 160ff; BBacon, Jesus and the Law: JBL 47, 1928, 203–31; BBranscomb, Jes. and the Law of Moses 1930; WKümmel, Jes. u. d. jüd. Traditionsged.: ZNW 33, ’34, 105–30; JHempel, D. synopt. Jesus u. d. AT: ZAW 56, ’38, 1–34.—Lk-Ac: JJervell, HTR 64, ’71, 21–36.—EGrafe, D. paulin. Lehre vom Gesetz2 1893; HCremer, D. paulin. Rechtfertigungslehre 1896, 84ff; 363ff; FSieffert, D. Entwicklungslinie d. paul. Gesetzeslehre: BWeiss Festschr. 1897, 332–57; WSlaten, The Qualitative Use of <span class=\"greek\">νόμος</span> in the Pauline Ep.: AJT 23, 1919, 213ff; HMosbech, Pls’ Laere om Loven: TT 4/3, 1922, 108–37; 177–221; EBurton, ICC, Gal 1921, 443–60; PFeine, Theol. des NT6 ’34, 208–15 (bibliografia); PBenoit, La Loi et la Croix d’après S. Paul (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:7</a>–8:4): RB 47, ’38, 481–509; CMaurer, D. Gesetzeslehre des Pls ’41; PBläser, D. Gesetz b. Pls ’41; BReicke, JBL 70, ’51, 259–76; GBornkamm, Das Ende d. Gesetzes ’63; HRaisänen, Paul and the Law2 ’87; PRichardson/SWesterholm e outros, Law in Religious Communities in the Rom. Period, ’91 (Torah and Nomos); MNobile, La Torà al tempo di Paolo, alcune ri-flessioni: Atti del IV simposio di Tarso su S. Paolo Apostolo, ed. LPadovese ’96, 93–106 (bibliografia 93f, n. 1).—Dodd 25–41.—B. 1358; 1419; 1421. DELG s.v. <span class=\"greek\">νέμω</span> Ic. Schmidt, Syn. I 333–47. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νοσέω</span> (<span class=\"greek\">νόσος</span>), particípio aoristo <span class=\"greek\">νοσήσας</span> TestJob 1:2; 35:3 (Aeschyl., Hdt. e outros; SIG 943, 5; papiros, TestJob; TestZeb 6:5; ParJer, Tat., Ath.), estar doente, enfermo; em nossa literatura, somente figuradamente (X., Mem. 3, 5, 18 e outros; Diod S 11, 86, 3; Heraclit. Sto. 69 p. 89, 20; Wsd 17:8; Philo, Leg. All. 3, 211; Jos., Ant. 16, 244; 18, 25): <span class=\"greek\">νοσεῖν</span> <span class=\"greek\">περί</span> <span class=\"greek\">τι</span>, sofrer de uma disposição mórbida quanto a algo, ter desejo doentio de alguma coisa (Plut., Mor. 54f <span class=\"greek\">ν</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">δόξαν</span>): <span class=\"greek\">περὶ</span> <span class=\"greek\">ζητήσεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λογομαχίας</span> (ver <span class=\"greek\">ζήτησις</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a>.—DELG s.v. <span class=\"greek\">νόσος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0246-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόσημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νόσημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">νόσος</span> por meio de <span class=\"greek\">νοσέω</span>; autores trágicos, Thu. e outros; Chion, Ep. 14, 2; Artem. 3, 51; PRein II, 92, 12 [IV a.d.]; PCairMasp 159, 40 [VI a.d.]; TestSol 11:2; Philo; Jos., Ant. 8, 45, C. Ap. 1, 282), doença: <span class=\"greek\">ᾧ</span> <span class=\"greek\">δήποτε</span> <span class=\"greek\">κατείχετο</span> <span class=\"greek\">νοσήματι</span>, qualquer que fosse a doença de que padecia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a> v.l.—DELG s.v. <span class=\"greek\">νόσος</span>. TW.</p></section></article>\n"};
